  // Fisher–Yates — used to shuffle both question order and each question's own choices.
  const shuffleArray = <T,>(items: T[]): T[] => {
    const copy = [...items];
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  };

  // Same tiering used for subject mastery accuracy everywhere it's shown — also used to
  // detect a genuine "academic improvement" (a subject crossing upward into a better tier)
  // worth notifying about, as opposed to every single answered question.
  type MasteryTier = 'weak' | 'developing' | 'mastered';
  const masteryTierOf = (accuracyPct: number): MasteryTier => (accuracyPct >= 80 ? 'mastered' : accuracyPct >= 50 ? 'developing' : 'weak');
  const MASTERY_TIER_RANK: Record<MasteryTier, number> = { weak: 0, developing: 1, mastered: 2 };


  /**
   * Immersive battle mode — fullscreen + landscape lock while the player is anywhere
   * inside the "Enter battle" flow (roaming -> briefing -> battle), released the moment
   * they leave it. Orientation lock only works while the page is actually fullscreen
   * (and only on devices/browsers that support the Screen Orientation API), so both
   * calls are wrapped and best-effort: if either is unavailable or blocked, the battle
   * still plays fine windowed/portrait, it just skips the immersive treatment.
   */
  const enterImmersiveBattle = async () => {
    try {
      const root = document.documentElement as HTMLElement & { webkitRequestFullscreen?: () => Promise<void> };
      if (!document.fullscreenElement) {
        if (root.requestFullscreen) await root.requestFullscreen();
        else if (root.webkitRequestFullscreen) await root.webkitRequestFullscreen();
      }
    } catch { /* fullscreen can be denied (desktop without a gesture, iframe, etc.) — non-fatal */ }
    try {
      const orientation = window.screen?.orientation as (ScreenOrientation & { lock?: (o: string) => Promise<void> }) | undefined;
      if (orientation?.lock) await orientation.lock('landscape');
    } catch { /* orientation lock needs fullscreen + mobile support — non-fatal elsewhere */ }
  };

  const exitImmersiveBattle = () => {
    try {
      const orientation = window.screen?.orientation as (ScreenOrientation & { unlock?: () => void }) | undefined;
      orientation?.unlock?.();
    } catch { /* ignore */ }
    try {
      const doc = document as Document & { webkitExitFullscreen?: () => Promise<void>; webkitFullscreenElement?: Element };
      if (document.fullscreenElement || doc.webkitFullscreenElement) {
        if (document.exitFullscreen) document.exitFullscreen().catch(() => {});
        else if (doc.webkitExitFullscreen) doc.webkitExitFullscreen();
      }
    } catch { /* ignore */ }
  };

  const FOCUS_DURATION_SECONDS = 25 * 60;
  const FOCUS_XP_REWARD = 100;
  const FOCUS_COIN_REWARD = 40;
  const XP_PER_LEVEL = 240;
  const getLevelInfo = (xp: number) => {
    const level = Math.floor(xp / XP_PER_LEVEL) + 1;
    const floorXp = (level - 1) * XP_PER_LEVEL;
    const ceilingXp = level * XP_PER_LEVEL;
    const progressPct = Math.min(100, Math.round(((xp - floorXp) / XP_PER_LEVEL) * 100));
    return { level, floorXp, ceilingXp, progressPct };
  };
  // Rank titles for the Profile page — thresholds deliberately match the campus's own
  // recommendedLevel breakpoints (1 / 3 / 5 / 8 from CAMPUS_CHALLENGERS), so "your title
  // just changed" lines up with "you're now ready for the next district."
  const LEVEL_TITLES: [number, string][] = [
    [1, 'Freshman Recruit'],
    [3, 'Rising Scholar'],
    [5, "Dean's List Contender"],
    [8, 'Campus Legend'],
  ];
  const getLevelTitle = (level: number) => LEVEL_TITLES.reduce((title, [minLevel, name]) => (level >= minLevel ? name : title), LEVEL_TITLES[0][1]);

  const makeDefaultAvatar = (): AvatarConfig => ({
    gender: 'neutral', skin: '#e9af54', hair: 'short', hairColor: '#2d1b2e',
    topType: 'tshirt', topColor: 'indigo', bottomType: 'pants', shoes: 'dark',
  });
  // Builds a fresh profile for a signed-in Firebase Auth user who doesn't have a
  // Firestore doc yet. Pulls the real name/email off the auth user (displayName /
  // email) instead of a hardcoded placeholder — falls back to deriving a name from
  // the email's local part, and only to a generic label if neither is available.
  const makeDefaultProfile = (authUser?: User | null): Profile => {
    const derivedName = authUser?.displayName?.trim() || authUser?.email?.split('@')[0] || 'Player';
    return { name: derivedName, email: authUser?.email ?? '', strand: 'STEM', avatar: makeDefaultAvatar() };
  };
  const makeFreshGameState = (): GameState => ({ coins: 0, xp: 0, quests: initialQuests.map((quest) => ({ ...quest })), owned: [], equipped: null, studyMinutes: 0, activityDates: [], subjectMastery: {} });
  const getInitials = (name: string) => name.split(' ').filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase() || 'PL';

  const toISODate = (date: Date) => {
    const offset = date.getTimezoneOffset();
    return new Date(date.getTime() - offset * 60000).toISOString().slice(0, 10);
  };
  const addDays = (date: Date, amount: number) => { const copy = new Date(date); copy.setDate(copy.getDate() + amount); return copy; };
  const computeStreak = (activityDates: string[]) => {
    const set = new Set(activityDates);
    let streak = 0;
    let cursor = new Date();
    if (!set.has(toISODate(cursor))) cursor = addDays(cursor, -1);
    while (set.has(toISODate(cursor))) { streak++; cursor = addDays(cursor, -1); }
    return streak;
  };
  const lastSevenDays = () => {
    const days: { iso: string; label: string }[] = [];
    for (let i = 6; i >= 0; i--) {
      const date = addDays(new Date(), -i);
      days.push({ iso: toISODate(date), label: date.toLocaleDateString('en-US', { weekday: 'narrow' }) });
    }
    return days;
  };

  // Firestore helpers for the `players/{uid}` document. Kept thin and separate from the
  // React state layer below so the App component can stay focused on optimistic local
  // updates + background syncing rather than raw Firestore calls everywhere.
  const loadPlayerDoc = async (uid: string): Promise<StoredAccount | null> => {
    const snap = await getDoc(doc(db, 'players', uid));
    if (!snap.exists()) return null;
    const data = snap.data() as StoredAccount;
    // Older accounts predate the subjectMastery field — backfill it rather than letting
    // downstream code (e.g. the Academic Mastery panel) deal with `undefined`.
    return { ...data, game: { ...data.game, subjectMastery: data.game.subjectMastery ?? {} } };
  };
  const savePlayerDoc = (uid: string, data: StoredAccount) => setDoc(doc(db, 'players', uid), data);

  // Firebase throws structured errors with a `.code` like 'auth/wrong-password'. This
  // maps the ones players are actually likely to hit into copy that matches the app's
  // voice, and falls back to the raw Firebase message for anything unexpected.
  const authErrorMessage = (err: unknown): string => {
    const code = (err as { code?: string })?.code ?? '';
    switch (code) {
      case 'auth/invalid-credential':
      case 'auth/wrong-password':
      case 'auth/user-not-found':
        return 'Incorrect email or password.';
      case 'auth/email-already-in-use':
        return 'An account with that email already exists. Try logging in instead.';
      case 'auth/invalid-email':
        return 'That email address doesn\'t look right.';
      case 'auth/weak-password':
        return 'Use at least 6 characters to protect your player file.';
      case 'auth/too-many-requests':
        return 'Too many attempts — please wait a moment and try again.';
      case 'auth/network-request-failed':
        return 'Network error — check your connection and try again.';
      case 'auth/requires-recent-login':
        return 'For security, please log out and back in before changing this.';
      default:
        return (err as { message?: string })?.message ?? 'Something went wrong. Please try again.';
    }
  };

  /* =====================================================================================
  * ERROR BOUNDARY
  * ===================================================================================== */
  class ErrorBoundary extends Component<{ children: ReactNode }, { error: Error | null }> {
    state = { error: null as Error | null };
    static getDerivedStateFromError(error: Error) { return { error }; }
    componentDidCatch(error: Error, info: ErrorInfo) { console.error(error, info.componentStack); }
    render() {
      if (this.state.error) return <div className="auth-screen"><div className="auth-card"><div className="eyebrow">SYSTEM SIGNAL LOST</div><h1 className="auth-title">Reload the<br /><span>run.</span></h1><p className="auth-copy">DERIOUX hit an unexpected error. Refresh the page to return to your player file.</p><button className="btn-primary w-full" onClick={() => window.location.reload()}>Reload DERIOUX <RotateCcw size={15} /></button></div></div>;
      return this.props.children;
    }
  }

